	const FVector2D InputVal = InputActionValue.Get<FVector2D>();

	// 根据输入值调整玩家的俯仰角(pitch)
	AddControllerPitchInput(-InputVal.Y);
	// 根据输入值调整玩家的偏航角(yaw)
	AddControllerYawInput(InputVal.X);
